with unpacked as (select id, currency, tier_limits, tier_prices, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, slice(tier_limits, 1, 2) as first_two_limits, aggregate(tier_prices, cast(0 as double), (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, element_at(tier_prices, 1) as entry_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps from price_tiers where currency not in ('EUR', 'USD', 'THB')) select *, dense_rank() over (partition by currency order by avg_tier_price desc nulls first) as avg_tier_price_dense_rank, avg(avg_tier_price) over (partition by currency order by avg_tier_price, id rows between 6 preceding and current row) as avg_tier_price_avg_6, lead(entry_price, 1, 0) over (partition by currency order by entry_price, id) as next_entry_price, row_number() over (partition by currency order by entry_price, id) as row_seq, row_number() over (partition by currency order by avg_tier_price, id) as event_seq from unpacked
